function linea(tag,txt){const n=document.createElement(tag);n.textContent=txt;return n;}
boton.onclick=()=>{modal.hidden=false;lista.replaceChildren();for(const p of prods){const b=linea('button',p.codigo+' · '+p.descripcion);b.type='button';b.style.margin='5px';b.onclick=()=>cargar(p,b);lista.append(b)}};
async function cargar(p,b){lista.querySelectorAll('button').forEach(x=>x.disabled=true);const aviso=linea('p','Consultando...');lista.append(aviso);try{const url=new URL('peticiones_traspasos_api.php',location.href);url.search=new URLSearchParams({op:'matriz',origen:'<?=intval($detalle['origen_id'])?>',destino:'<?=intval($detalle['destino_id'])?>',producto_id:String(p.id)});const res=await fetch(url,{credentials:'same-origin',cache:'no-store'});const d=await res.json();if(!res.ok||d.error)throw Error(d.error||'Error de consulta');aviso.textContent=`${p.codigo} · ${p.descripcion} | HIDALGO: Almacén ${d.hidalgo.ALMACEN??'Sin conteo'}, Farmacia ${d.hidalgo.FARMACIA??'Sin conteo'} | TUXTLA: Almacén ${d.tuxtla.ALMACEN??'Sin conteo'}, Farmacia ${d.tuxtla.FARMACIA??'Sin conteo'} | TAPACHULA/TOSCANA compartido: ${d.tapachula_toscana.UNICO} (referencial)`;}catch(e){aviso.textContent=e.message}finally{lista.querySelectorAll('button').forEach(x=>x.disabled=false)}}
